// ============================================================================
// JESD204C_apb: APB4 register wrapper around JESD204C_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/JESD204C.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/JESD204C.md
// ============================================================================
module JESD204C_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic tx_p,
  input logic rx_p
);
  localparam logic [31:0] ID_VALUE = 32'h4A430200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [13:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd14) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [3:0]    c_cfg_e;
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic [63:0]   c_tx_data;
  logic [6:0]    c_tx_cmd;
  logic          c_tx_mb_start;
  logic          c_tx_underrun;
  logic          c_rx_valid;
  logic [63:0]   c_rx_data;
  logic          c_rx_mb_start;
  logic          c_rx_emb_start;
  logic          c_rx_mb_valid;
  logic [6:0]    c_rx_cmd;
  logic          c_rx_crc_err;
  logic          c_sh_lock;
  logic          c_emb_lock;
  logic          c_err_sh;
  logic          c_err_emb;
  JESD204C_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .tx_p(tx_p),
    .rx_p(rx_p),
    .cfg_e(c_cfg_e),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .tx_data(c_tx_data),
    .tx_cmd(c_tx_cmd),
    .tx_mb_start(c_tx_mb_start),
    .tx_underrun(c_tx_underrun),
    .rx_valid(c_rx_valid),
    .rx_data(c_rx_data),
    .rx_mb_start(c_rx_mb_start),
    .rx_emb_start(c_rx_emb_start),
    .rx_mb_valid(c_rx_mb_valid),
    .rx_cmd(c_rx_cmd),
    .rx_crc_err(c_rx_crc_err),
    .sh_lock(c_sh_lock),
    .emb_lock(c_emb_lock),
    .err_sh(c_err_sh),
    .err_emb(c_err_emb)
  );

  // ---------------- registers ----------------
  logic [9:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [3:0] r_CFG;   // 12'h014 CFG
  logic [6:0] r_CMD;   // 12'h018 CMD
  logic [31:0] h_TX0;   // 12'h01C TX0 holding register
  logic [31:0] h_TX1;   // 12'h020 TX1 holding register
  logic [31:0] h_RX0;   // 12'h024 RX0 holding register
  logic [31:0] h_RX1;   // 12'h028 RX1 holding register
  logic [1:0] h_RX2;   // 12'h02C RX2 holding register
  logic [7:0] h_MB;   // 12'h030 MB holding register
  logic full_TX;
  logic avail_RX;
  logic avail_MB;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CFG <= 4'h0;
      r_CMD <= 7'h0;
      h_TX0 <= '0;
      h_TX1 <= '0;
      h_RX0 <= '0;
      h_RX1 <= '0;
      h_RX2 <= '0;
      h_MB <= '0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
      avail_MB <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[9:0] & wmask[9:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[9:0]) | (PWDATA[9:0] & wmask[9:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CFG <= (r_CFG & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[6]) r_CMD <= (r_CMD & ~wmask[6:0]) | (PWDATA[6:0] & wmask[6:0]);
      if (wr && hit[7] && !full_TX) h_TX0 <= (h_TX0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8] && !full_TX) h_TX1 <= (h_TX1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tx_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[11]))) begin
        h_RX0[31:0] <= c_rx_data[31:0];
        h_RX1[31:0] <= c_rx_data[63:32];
        h_RX2[0:0] <= c_rx_mb_start;
        h_RX2[1:1] <= c_rx_emb_start;
        avail_RX <= 1'b1;
      end else if (rd && hit[11]) avail_RX <= 1'b0;
      if (c_rx_mb_valid && (!avail_MB || (rd && hit[12]))) begin
        h_MB[6:0] <= c_rx_cmd[6:0];
        h_MB[7:7] <= c_rx_crc_err;
        avail_MB <= 1'b1;
      end else if (rd && hit[12]) avail_MB <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_e = r_CFG[3:0];
  assign c_tx_cmd = r_CMD[6:0];
  assign c_tx_data[31:0] = h_TX0[31:0];
  assign c_tx_data[63:32] = h_TX1[31:0];
  assign c_tx_valid = full_TX;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_tx_mb_start;
    irq_set[1] = c_tx_underrun;
    irq_set[2] = c_err_sh;
    irq_set[3] = c_err_emb;
    irq_set[4] = full_TX & c_tx_ready;
    irq_set[5] = wr & (hit[7] | hit[8]) & full_TX;
    irq_set[6] = c_rx_valid & (~avail_RX | (rd & hit[11]));
    irq_set[7] = c_rx_valid & avail_RX & ~(rd & hit[11]);
    irq_set[8] = c_rx_mb_valid & (~avail_MB | (rd & hit[12]));
    irq_set[9] = c_rx_mb_valid & avail_MB & ~(rd & hit[12]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [2:0] flags = {avail_MB, avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CFG);
      10'd6: apb_rdata = 32'(r_CMD);
      10'd7: apb_rdata = 32'(h_TX0);
      10'd8: apb_rdata = 32'(h_TX1);
      10'd9: apb_rdata = 32'(h_RX0);
      10'd10: apb_rdata = 32'(h_RX1);
      10'd11: apb_rdata = 32'(h_RX2);
      10'd12: apb_rdata = 32'(h_MB);
      10'd13: apb_rdata = 32'({c_emb_lock, c_sh_lock});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
